import { Context, Effect, Layer } from 'effect'
import { RuntimeError } from '@hrbr/runtime-core'

export interface RuntimeHttpRawResult {
  readonly result?: unknown
  readonly content_type?: string | null | undefined
  readonly upstream_status?: number | null | undefined
  readonly upstream_traceparent?: string | undefined
  readonly [key: string]: unknown
}

export interface RuntimeHttpInvocationInput {
  readonly namespace: string
  readonly toolName: string
  readonly invoke: () => Promise<RuntimeHttpRawResult>
}

export interface RuntimeHttpInvocationResult {
  readonly raw: RuntimeHttpRawResult
  readonly value: unknown
  readonly contentType?: string | null | undefined
  readonly upstreamStatus?: number | null | undefined
  readonly upstreamTraceparent?: string | undefined
}

export interface RuntimeHttpProvider {
  readonly invoke: (
    input: RuntimeHttpInvocationInput
  ) => Effect.Effect<RuntimeHttpInvocationResult, RuntimeError>
}

export const RuntimeHttpProvider = Context.Service<RuntimeHttpProvider>(
  '@hrbr/runtime-provider-http/RuntimeHttpProvider'
)

export const RuntimeHttpProviderLive = Layer.succeed(RuntimeHttpProvider, {
  invoke: (input) =>
    Effect.tryPromise({
      try: async () => finalizeRuntimeHttpResult(await input.invoke()),
      catch: (cause) =>
        new RuntimeError('provider', 'HTTP provider invocation failed', {
          namespace: input.namespace,
          toolName: input.toolName,
          cause,
        }),
    }),
})

export function finalizeRuntimeHttpResult(raw: RuntimeHttpRawResult): RuntimeHttpInvocationResult {
  return {
    raw,
    value: Object.hasOwn(raw, 'result') ? raw.result : raw,
    contentType: raw.content_type,
    upstreamStatus: raw.upstream_status,
    upstreamTraceparent: raw.upstream_traceparent,
  }
}
